const POST_PROCESSING = false;
const { Point, Line, Polygon } = EpiShapeSvg;
const { EpiColors } = EpiColorsPckg;
const PENS = ["red", "blue", "black"]; // 
let svgStr;

function setup() {
	createCanvas(windowWidth, windowHeight);
	frameRate(30);

	background(212);
	stroke(0);
	strokeWeight(3.75);
	noFill();
}

function draw() {
	// blendMode(BLEND);
	background(212);
	// blendMode(ADD);
	translate(width/2, height/2);

	svgStr = `<svg width="${width}" height="${height}" xmlns="http://www.w3.org/2000/svg">\n`;
	svgStr += `<g id="none" stroke="0" fill="none">\n`;
	for (let i = 0; i < PENS.length; i++) {
		stroke(EpiColors.getColor(PENS[i], 160));
		drawSpiral(11+i*1, 5);
	}
	svgStr += `</g>\n`;
	svgStr += `</svg>`;

	if (POST_PROCESSING) {		
		translate(-width/2, -height/2);
		const imgFull = get(0, 0, width, height)
		const NN = 15;
		const WW = Math.ceil(width / NN);
		for (let i = 1; i < NN; i++) {
			const j = i % 2 ? i + 1 : i - 1; // 2, 1, 4, 3, 6, 5, ...
			// console.log(`${i}, ${j}`)
			const x = j * WW;
			image(imgFull.get(x, 0, min(WW, width+WW-x), height), i*WW, 0)
		}
	}

	// // noLoop() removed for animation
}

function drawSpiral(i, len = 2) {
	const ptsArr = [];
	const nf = max(width, height)/5; // 45; // noise factor
	const nl = nf/5; // 20; // len of dev-vector
	let dmax = max(width, height) * 0.9;
	let d = dmax;
	let a = -frameCount/60 + i;
	while(d > len) {
		const f = map(d, len, dmax, 0, 1); // pow(1 - len/d, 2); // 1..0
		// console.log(`${f}, ${d}, ${len}`)
		let u = PI * d;
		const da = len/u * TAU;
		a += da;
		d -= da * len;
		var x = cos(a) * d * 0.5;
		const y = sin(a) * d * 0.5;
		const n = noise(x/300 + i, y/300 + i, frameCount/300) * TAU;
		const scl = len;

		/*
		const dx = scl * cos(n) * n;
		const dy = scl * sin(n) * (1-n);
		vertex(x + dx, y + dy);
		*/

		const dv = createVector(nl*f, 0);
		dv.rotate(noise(i+(width+x)/nf, i+(height+y)/nf, i+frameCount/222)*TAU)
		// vertex(x + dv.x, y + dv.y);
		ptsArr.push({x: x + dv.x, y: y + dv.y});
	}

	const spiralPoly = new Polygon(ptsArr);
	spiralPoly.drawShape();

	svgStr += spiralPoly.toSVG() + "\n";
}

function mousePressed() {
	if (mouseButton !== RIGHT && (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) > width*0.1) setup();
}

function keyPressed() {
	if (key === "s") saveFile("epi_spiral_noise")
}
